@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=chart.grid value=show operator=eq phase=result key_words="grid lines"

@f1 w.request.filler text=also
@r1 w.request.request act=change mood=do words="set the colour map yellow through red" predicate=set
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.palette words="yellow through red" operator=eq phase=result key_words="the colour map"
@r2 w.request.request act=change mood=do words="give it the title Sensor surface" predicate=give
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=context
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=chart.title value="Sensor surface" operator=eq phase=result key_words=title
@f2 w.request.filler text="that's the tweak"
